    (65, 'Challenger Model', 'Calculated Total - VZ Wls Srvc and Fiber bb', 'PC.20P1111111', 'PROFIT_CENTER', 'ALL', 'AC.4110', 'STATISTICS', 'ALL', 'SERVICE_TYPE', 'ALL', 'ALL', 'ALL', 'MKT.PRIM_MKT', 'ALL', 'ALL', 'PRODUCT', 'ALL', 'EQUIPMENT', 'ALL', 'DISTRIBUTION_CHANNEL', 'ALL', NULL, FALSE, NULL),
    (66, 'Challenger Model', 'Consumer - WLS Equipment Revenue', 'PC.20P2000000', 'PROFIT_CENTER', 'ALL', 'AC.4200', 'STATISTICS', 'ALL', 'SERVICE_TYPE', 'ALL', 'ALL', 'ALL', 'MKT.PRIM_MKT', 'ALL', 'ALL', 'PRODUCT', 'ALL', 'EQUIPMENT', 'ALL', 'DISTRIBUTION_CHANNEL', 'ALL', NULL, TRUE, NULL),
    (67, 'Challenger Model', 'Business - WLS Equipment Revenue', 'PC.20P1000000', 'PROFIT_CENTER', 'ALL', 'AC.4200', 'STATISTICS', 'ALL', 'SERVICE_TYPE', 'ALL', 'ALL', 'ALL', 'MKT.PRIM_MKT', 'ALL', 'ALL', 'PRODUCT', 'ALL', 'EQUIPMENT', 'ALL', 'DISTRIBUTION_CHANNEL', 'ALL', NULL, TRUE, NULL),
    (68, 'Challenger Model', 'Corporate - WLS Equipment Revenue', 'PC.20P3000000', 'PROFIT_CENTER', 'ALL', 'AC.4200', 'STATISTICS', 'ALL', 'SERVICE_TYPE', 'ALL', 'ALL', 'ALL', 'MKT.PRIM_MKT', 'ALL', 'ALL', 'PRODUCT', 'ALL', 'EQUIPMENT', 'ALL', 'DISTRIBUTION_CHANNEL', 'ALL', NULL, TRUE, '3 Months Average'),
    (69, 'Challenger Model', 'Consumer - Volume/Services', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Calculated Consumer - Volume/Services] - [Consumer - Postpaid FWA] - [Consumer - Promo Amortization] - [Consumer - Value prepaid] - [Consumer - Reseller]', TRUE, NULL),
    (70, 'Challenger Model', 'Business - Volume/Services', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Calculated Business - Volume/Services] - [Business - Postpaid FWA] - [Business - Promo Amortization]', TRUE, NULL),
    (71, 'Challenger Model', 'Fiber', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Calculated Corporate - VZ Fiber] + [Consumer - VZ Fiber] + [Business - VZ Fiber] + [Calculated Corporate - FTR Fiber] + [Consumer - FTR Fiber] + [Business - FTR Fiber]', TRUE, NULL),
    (72, 'Challenger Model', 'Mobility and Broadband Service Revenue', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Fiber] + [Consumer - Volume/Services] + [Business - Volume/Services] + [Consumer - Reseller] + [Consumer - Value prepaid] + [Consumer - Promo Amortization] + [Business - Promo Amortization] + [Business - Postpaid FWA] + [Consumer - Postpaid FWA]', TRUE, NULL),
    (73, 'Challenger Model', 'Corporate - VZ WLN Less Fiber', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Calculated Corporate - VZ Only Total WLN Operating Revenue] - [Calculated Corporate - VZ Fiber]', TRUE, NULL),
    (74, 'Challenger Model', 'Consumer - VZ WLN Less Fiber', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Calculated Consumer - VZ Only Total WLN Operating Revenue] - [Consumer - VZ Fiber]', TRUE, NULL),
    (75, 'Challenger Model', 'Business - VZ WLN Less Fiber', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Calculated Business - VZ Only Total WLN Operating Revenue] - [Business - VZ Fiber]', TRUE, NULL),
    (76, 'Challenger Model', 'Consumer - FTR WLN Less Fiber', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Calculated Consumer - FTR Only Total WLN Operating Revenue] - [Consumer - FTR Fiber]', TRUE, NULL),
    (77, 'Challenger Model', 'Business - FTR WLN Less Fiber', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Calculated Business - FTR Only Total WLN Operating Revenue] - [Business - FTR Fiber]', TRUE, NULL),
    (78, 'Challenger Model', 'Corporate and Other', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Calculated Total - VZ Service and other Rev] - [Calculated Total - VZ Wls Srvc and Fiber bb] - [Eliminations] - [Consumer - Other Wireless Revenue] - [Business - Other Wireless Revenue] - [Corporate - Other Wireless Revenue] - ([Corporate - VZ WLN Less Fiber] + [Consumer - VZ WLN Less Fiber] + [Business - VZ WLN Less Fiber] + [Consumer - FTR WLN Less Fiber] + [Business - FTR WLN Less Fiber])', TRUE, NULL),
    (79, 'Challenger Model', 'Total Operating Revenues', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Mobility and Broadband Service Revenue] + [Corporate - VZ WLN Less Fiber] + [Consumer - VZ WLN Less Fiber] + [Business - VZ WLN Less Fiber] + [Consumer - FTR WLN Less Fiber] + [Business - FTR WLN Less Fiber] + [Consumer - Other Wireless Revenue] + [Business - Other Wireless Revenue] + [Corporate - Other Wireless Revenue] + [Corporate and Other] + [Eliminations] + [Consumer - WLS Equipment Revenue] + [Business - WLS Equipment Revenue] + [Corporate - WLS Equipment Revenue]', TRUE, NULL)
  ])
),
Config AS (
  SELECT
    Config_ID,
    TRIM(LineItem) AS LineItem,
    IF((ProfitCentre IS NULL OR TRIM(ProfitCentre) = '' OR UPPER(TRIM(ProfitCentre)) IN ('ALL', 'NA')), 'ALL', TRIM(ProfitCentre)) AS ProfitCentre,
    NULLIF(TRIM(ProfitCentreHierarchyName), '') AS ProfitCentreHierarchyName,
    IF((Account IS NULL OR TRIM(Account) = '' OR UPPER(TRIM(Account)) IN ('ALL', 'NA')), 'ALL', TRIM(Account)) AS Account,
    NULLIF(TRIM(AccountHierarchy), '') AS AccountHierarchy,
    IF((CompanyCode IS NULL OR TRIM(CompanyCode) = '' OR UPPER(TRIM(CompanyCode)) IN ('ALL', 'NA')), 'ALL', TRIM(CompanyCode)) AS CompanyCode,
    IF((Market IS NULL OR TRIM(Market) = '' OR UPPER(TRIM(Market)) IN ('ALL', 'NA')), 'ALL', TRIM(Market)) AS Market
  FROM config_csv
  WHERE (Formula IS NULL OR TRIM(Formula) = '')
),
profitcentre_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.ProfitCentre) AS ProfitCentreGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.ProfitCentre = H.parent
    AND H.dimension_name = 'Profit_Center'
    AND (CASE WHEN C.ProfitCentreHierarchyName IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.ProfitCentreHierarchyName END)
  WHERE C.ProfitCentre <> 'ALL'
),
account_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Account) AS AccountGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Account = H.parent
    AND H.dimension_name = 'Account'
    AND (CASE WHEN C.AccountHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.AccountHierarchy END)
  WHERE C.Account <> 'ALL'
),
companycode_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.CompanyCode) AS CompanyCodeGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.CompanyCode = H.parent
    AND H.dimension_name = 'Company_Code'
    AND (H.is_primary = TRUE)
  WHERE C.CompanyCode <> 'ALL'
),
market_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Market) AS MarketGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Market = H.parent
    AND H.dimension_name = 'Market'
    AND (H.is_primary = TRUE)
  WHERE C.Market <> 'ALL'
),
actuals AS (
  SELECT T.year, T.period, T.profit_center, T.Account, T.Company_Code, T.Market, SUM(T.amount) AS amount
  FROM `vz-it-np-j0nv-dev-oddo-0.od_published_epm.epm_p00all_actuals_fullhist_v` T
  INNER JOIN (SELECT DISTINCT ProfitCentreGranular FROM profitcentre_mapping) F_ProfitCentre
    ON F_ProfitCentre.ProfitCentreGranular = T.profit_center
  INNER JOIN (SELECT DISTINCT AccountGranular FROM account_mapping) F_Account
    ON F_Account.AccountGranular = T.Account
  INNER JOIN (SELECT DISTINCT MarketGranular FROM market_mapping) F_Market
    ON F_Market.MarketGranular = T.Market
  WHERE T.year IN (
      SELECT FORMAT_DATE('FY%y', DATE_SUB(DATE_ADD(CURRENT_DATE(), INTERVAL 0 MONTH), INTERVAL i YEAR))
      FROM UNNEST(GENERATE_ARRAY(0, 4)) AS i)
  GROUP BY T.year, T.period, T.profit_center, T.Account, T.Company_Code, T.Market
),
base_values AS (
  SELECT C.LineItem, A.year AS year, A.period AS month, SUM(A.amount) AS Amount
  FROM actuals A
  INNER JOIN profitcentre_mapping M_ProfitCentre
    ON M_ProfitCentre.ProfitCentreGranular = A.profit_center
  INNER JOIN Config C
    ON C.Config_ID = M_ProfitCentre.Config_ID
  INNER JOIN account_mapping M_Account
    ON M_Account.Config_ID = C.Config_ID
    AND M_Account.AccountGranular = A.Account
  INNER JOIN market_mapping M_Market
    ON M_Market.Config_ID = C.Config_ID
    AND M_Market.MarketGranular = A.Market
  LEFT JOIN companycode_mapping M_CompanyCode
    ON M_CompanyCode.Config_ID = C.Config_ID
    AND M_CompanyCode.CompanyCodeGranular = A.Company_Code
  WHERE
    (C.CompanyCode = 'ALL' OR M_CompanyCode.Config_ID IS NOT NULL)
  GROUP BY C.LineItem, A.year, A.period
)
SELECT LineItem, year, month, Amount
FROM base_values;

WITH
monthly_summary AS (
  SELECT year, month, LineItem, CAST(COALESCE(SUM(Amount), 0) AS FLOAT64) AS Amount
  FROM `base_values`
  GROUP BY year, month, LineItem
),

monthly_summary_dated AS (
  -- month_date orders the months for LAG / rolling / roll-forward; a year or month it cannot read stops the query
  SELECT
    year, month, LineItem, Amount,
    IF(month_date IS NULL,
       ERROR(FORMAT('cannot turn year %T / month %T into a date (fix the month mapping or add the period to EXCLUDED_PERIODS)', year, month)),
       month_date) AS month_date
  FROM (
    SELECT *, SAFE.DATE(IF(year_num < 100, 2000 + year_num, year_num), month_num, 1) AS month_date
    FROM (
      SELECT
        *,
        SAFE_CAST(REGEXP_REPLACE(CAST(year AS STRING), r'^[Ff][Yy]', '') AS INT64) AS year_num,
        CASE LOWER(TRIM(CAST(month AS STRING)))
          WHEN 'jan' THEN 1 WHEN 'january' THEN 1
          WHEN 'feb' THEN 2 WHEN 'february' THEN 2
          WHEN 'mar' THEN 3 WHEN 'march' THEN 3
          WHEN 'apr' THEN 4 WHEN 'april' THEN 4
          WHEN 'may' THEN 5
          WHEN 'jun' THEN 6 WHEN 'june' THEN 6
          WHEN 'jul' THEN 7 WHEN 'july' THEN 7
          WHEN 'aug' THEN 8 WHEN 'august' THEN 8
          WHEN 'sep' THEN 9 WHEN 'september' THEN 9
          WHEN 'oct' THEN 10 WHEN 'october' THEN 10
          WHEN 'nov' THEN 11 WHEN 'november' THEN 11
          WHEN 'dec' THEN 12 WHEN 'december' THEN 12
          ELSE SAFE_CAST(TRIM(CAST(month AS STRING)) AS INT64)
        END AS month_num
      FROM monthly_summary
    )
  )
),

combined_0 AS (
  SELECT year, month, month_date, LineItem, Amount FROM monthly_summary_dated
),

tier_1_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Consumer - Volume/Services = [Calculated Consumer - Volume/Services] - [Consumer - Postpaid FWA] - [Consumer - Promo Amortization] - [Consumer - Value prepaid] - [Consumer - Reseller]  (Config_ID 69)
    SUM(IF(LineItem = 'Calculated Consumer - Volume/Services', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Postpaid FWA', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Promo Amortization', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Value prepaid', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Reseller', Amount, 0)) AS f_69,
    -- Business - Volume/Services = [Calculated Business - Volume/Services] - [Business - Postpaid FWA] - [Business - Promo Amortization]  (Config_ID 70)
    SUM(IF(LineItem = 'Calculated Business - Volume/Services', Amount, 0)) - SUM(IF(LineItem = 'Business - Postpaid FWA', Amount, 0)) - SUM(IF(LineItem = 'Business - Promo Amortization', Amount, 0)) AS f_70,
    -- Fiber = [Calculated Corporate - VZ Fiber] + [Consumer - VZ Fiber] + [Business - VZ Fiber] + [Calculated Corporate - FTR Fiber] + [Consumer - FTR Fiber] + [Business - FTR Fiber]  (Config_ID 71)
    SUM(IF(LineItem = 'Calculated Corporate - VZ Fiber', Amount, 0)) + SUM(IF(LineItem = 'Consumer - VZ Fiber', Amount, 0)) + SUM(IF(LineItem = 'Business - VZ Fiber', Amount, 0)) + SUM(IF(LineItem = 'Calculated Corporate - FTR Fiber', Amount, 0)) + SUM(IF(LineItem = 'Consumer - FTR Fiber', Amount, 0)) + SUM(IF(LineItem = 'Business - FTR Fiber', Amount, 0)) AS f_71,
    -- Corporate - VZ WLN Less Fiber = [Calculated Corporate - VZ Only Total WLN Operating Revenue] - [Calculated Corporate - VZ Fiber]  (Config_ID 73)
    SUM(IF(LineItem = 'Calculated Corporate - VZ Only Total WLN Operating Revenue', Amount, 0)) - SUM(IF(LineItem = 'Calculated Corporate - VZ Fiber', Amount, 0)) AS f_73,
    -- Consumer - VZ WLN Less Fiber = [Calculated Consumer - VZ Only Total WLN Operating Revenue] - [Consumer - VZ Fiber]  (Config_ID 74)
    SUM(IF(LineItem = 'Calculated Consumer - VZ Only Total WLN Operating Revenue', Amount, 0)) - SUM(IF(LineItem = 'Consumer - VZ Fiber', Amount, 0)) AS f_74,
    -- Business - VZ WLN Less Fiber = [Calculated Business - VZ Only Total WLN Operating Revenue] - [Business - VZ Fiber]  (Config_ID 75)
    SUM(IF(LineItem = 'Calculated Business - VZ Only Total WLN Operating Revenue', Amount, 0)) - SUM(IF(LineItem = 'Business - VZ Fiber', Amount, 0)) AS f_75,
    -- Consumer - FTR WLN Less Fiber = [Calculated Consumer - FTR Only Total WLN Operating Revenue] - [Consumer - FTR Fiber]  (Config_ID 76)
    SUM(IF(LineItem = 'Calculated Consumer - FTR Only Total WLN Operating Revenue', Amount, 0)) - SUM(IF(LineItem = 'Consumer - FTR Fiber', Amount, 0)) AS f_76,
    -- Business - FTR WLN Less Fiber = [Calculated Business - FTR Only Total WLN Operating Revenue] - [Business - FTR Fiber]  (Config_ID 77)
    SUM(IF(LineItem = 'Calculated Business - FTR Only Total WLN Operating Revenue', Amount, 0)) - SUM(IF(LineItem = 'Business - FTR Fiber', Amount, 0)) AS f_77
  FROM combined_0
  GROUP BY year, month, month_date
),

tier_1 AS (
  SELECT calc.year, calc.month, calc.month_date, item.LineItem, COALESCE(item.Amount, 0) AS Amount
  FROM tier_1_calc AS calc
  CROSS JOIN UNNEST(ARRAY<STRUCT<LineItem STRING, Amount FLOAT64>>[
    ('Consumer - Volume/Services', calc.f_69),
    ('Business - Volume/Services', calc.f_70),
    ('Fiber', calc.f_71),
    ('Corporate - VZ WLN Less Fiber', calc.f_73),
    ('Consumer - VZ WLN Less Fiber', calc.f_74),
    ('Business - VZ WLN Less Fiber', calc.f_75),
    ('Consumer - FTR WLN Less Fiber', calc.f_76),
    ('Business - FTR WLN Less Fiber', calc.f_77)
  ]) AS item
),

tier_1_names AS (
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Consumer - Volume/Services',
    'Business - Volume/Services',
    'Fiber',
    'Corporate - VZ WLN Less Fiber',
    'Consumer - VZ WLN Less Fiber',
    'Business - VZ WLN Less Fiber',
    'Consumer - FTR WLN Less Fiber',
    'Business - FTR WLN Less Fiber'
  ]) AS LineItem
),

combined_1 AS (
  -- anti-join: a calculated line item replaces source rows with the same name (no double counting)
  SELECT c.year, c.month, c.month_date, c.LineItem, c.Amount
  FROM combined_0 AS c
  LEFT JOIN tier_1_names AS n
    ON c.LineItem = n.LineItem
  WHERE n.LineItem IS NULL
  UNION ALL
  SELECT year, month, month_date, LineItem, Amount FROM tier_1
),

tier_2_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Mobility and Broadband Service Revenue = [Fiber] + [Consumer - Volume/Services] + [Business - Volume/Services] + [Consumer - Reseller] + [Consumer - Value prepaid] + [Consumer - Promo Amortization] + [Business - Promo Amortization] + [Business - Postpaid FWA] + [Consumer - Postpaid FWA]  (Config_ID 72)
    SUM(IF(LineItem = 'Fiber', Amount, 0)) + SUM(IF(LineItem = 'Consumer - Volume/Services', Amount, 0)) + SUM(IF(LineItem = 'Business - Volume/Services', Amount, 0)) + SUM(IF(LineItem = 'Consumer - Reseller', Amount, 0)) + SUM(IF(LineItem = 'Consumer - Value prepaid', Amount, 0)) + SUM(IF(LineItem = 'Consumer - Promo Amortization', Amount, 0)) + SUM(IF(LineItem = 'Business - Promo Amortization', Amount, 0)) + SUM(IF(LineItem = 'Business - Postpaid FWA', Amount, 0)) + SUM(IF(LineItem = 'Consumer - Postpaid FWA', Amount, 0)) AS f_72,
    -- Corporate and Other = [Calculated Total - VZ Service and other Rev] - [Calculated Total - VZ Wls Srvc and Fiber bb] - [Eliminations] - [Consumer - Other Wireless Revenue] - [Business - Other Wireless Revenue] - [Corporate - Other Wireless Revenue] - ([Corporate - VZ WLN Less Fiber] + [Consumer - VZ WLN Less Fiber] + [Business - VZ WLN Less Fiber] + [Consumer - FTR WLN Less Fiber] + [Business - FTR WLN Less Fiber])  (Config_ID 78)
    SUM(IF(LineItem = 'Calculated Total - VZ Service and other Rev', Amount, 0)) - SUM(IF(LineItem = 'Calculated Total - VZ Wls Srvc and Fiber bb', Amount, 0)) - SUM(IF(LineItem = 'Eliminations', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Other Wireless Revenue', Amount, 0)) - SUM(IF(LineItem = 'Business - Other Wireless Revenue', Amount, 0)) - SUM(IF(LineItem = 'Corporate - Other Wireless Revenue', Amount, 0)) - (SUM(IF(LineItem = 'Corporate - VZ WLN Less Fiber', Amount, 0)) + SUM(IF(LineItem = 'Consumer - VZ WLN Less Fiber', Amount, 0)) + SUM(IF(LineItem = 'Business - VZ WLN Less Fiber', Amount, 0)) + SUM(IF(LineItem = 'Consumer - FTR WLN Less Fiber', Amount, 0)) + SUM(IF(LineItem = 'Business - FTR WLN Less Fiber', Amount, 0))) AS f_78
  FROM combined_1
  GROUP BY year, month, month_date
),

tier_2 AS (
  SELECT calc.year, calc.month, calc.month_date, item.LineItem, COALESCE(item.Amount, 0) AS Amount
  FROM tier_2_calc AS calc
  CROSS JOIN UNNEST(ARRAY<STRUCT<LineItem STRING, Amount FLOAT64>>[
    ('Mobility and Broadband Service Revenue', calc.f_72),
    ('Corporate and Other', calc.f_78)
  ]) AS item
),

tier_2_names AS (
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Mobility and Broadband Service Revenue',
    'Corporate and Other'
  ]) AS LineItem
),

combined_2 AS (
  -- anti-join: a calculated line item replaces source rows with the same name (no double counting)
  SELECT c.year, c.month, c.month_date, c.LineItem, c.Amount
  FROM combined_1 AS c
  LEFT JOIN tier_2_names AS n
    ON c.LineItem = n.LineItem
  WHERE n.LineItem IS NULL
  UNION ALL
  SELECT year, month, month_date, LineItem, Amount FROM tier_2
),

tier_3_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Total Operating Revenues = [Mobility and Broadband Service Revenue] + [Corporate - VZ WLN Less Fiber] + [Consumer - VZ WLN Less Fiber] + [Business - VZ WLN Less Fiber] + [Consumer - FTR WLN Less Fiber] + [Business - FTR WLN Less Fiber] + [Consumer - Other Wireless Revenue] + [Business - Other Wireless Revenue] + [Corporate - Other Wireless Revenue] + [Corporate and Other] + [Eliminations] + [Consumer - WLS Equipment Revenue] + [Business - WLS Equipment Revenue] + [Corporate - WLS Equipment Revenue]  (Config_ID 79)
    SUM(IF(LineItem = 'Mobility and Broadband Service Revenue', Amount, 0)) + SUM(IF(LineItem = 'Corporate - VZ WLN Less Fiber', Amount, 0)) + SUM(IF(LineItem = 'Consumer - VZ WLN Less Fiber', Amount, 0)) + SUM(IF(LineItem = 'Business - VZ WLN Less Fiber', Amount, 0)) + SUM(IF(LineItem = 'Consumer - FTR WLN Less Fiber', Amount, 0)) + SUM(IF(LineItem = 'Business - FTR WLN Less Fiber', Amount, 0)) + SUM(IF(LineItem = 'Consumer - Other Wireless Revenue', Amount, 0)) + SUM(IF(LineItem = 'Business - Other Wireless Revenue', Amount, 0)) + SUM(IF(LineItem = 'Corporate - Other Wireless Revenue', Amount, 0)) + SUM(IF(LineItem = 'Corporate and Other', Amount, 0)) + SUM(IF(LineItem = 'Eliminations', Amount, 0)) + SUM(IF(LineItem = 'Consumer - WLS Equipment Revenue', Amount, 0)) + SUM(IF(LineItem = 'Business - WLS Equipment Revenue', Amount, 0)) + SUM(IF(LineItem = 'Corporate - WLS Equipment Revenue', Amount, 0)) AS f_79
  FROM combined_2
  GROUP BY year, month, month_date
),

tier_3 AS (
  SELECT calc.year, calc.month, calc.month_date, item.LineItem, COALESCE(item.Amount, 0) AS Amount
  FROM tier_3_calc AS calc
  CROSS JOIN UNNEST(ARRAY<STRUCT<LineItem STRING, Amount FLOAT64>>[
    ('Total Operating Revenues', calc.f_79)
  ]) AS item
),

tier_3_names AS (
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Total Operating Revenues'
  ]) AS LineItem
),

combined_3 AS (
  -- anti-join: a calculated line item replaces source rows with the same name (no double counting)
  SELECT c.year, c.month, c.month_date, c.LineItem, c.Amount
  FROM combined_2 AS c
  LEFT JOIN tier_3_names AS n
    ON c.LineItem = n.LineItem
  WHERE n.LineItem IS NULL
  UNION ALL
  SELECT year, month, month_date, LineItem, Amount FROM tier_3
),

output_items AS (
  -- line items whose FinalOutput is not N / NO / FALSE / 0
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Business - Postpaid FWA',
    'Consumer - Promo Amortization',
    'Consumer - Postpaid FWA',
    'Consumer - Reseller',
    'Business - Promo Amortization',
    'Consumer - Value prepaid',
    'Consumer - VZ Fiber',
    'Business - VZ Fiber',
    'Consumer - FTR Fiber',
    'Business - FTR Fiber',
    'Corporate - Wireless Service Revenue',
    'Consumer - Other Wireless Revenue',
    'Business - Other Wireless Revenue',
    'Corporate - Other Wireless Revenue',
    'Eliminations',
    'Consumer - WLS Equipment Revenue',
    'Business - WLS Equipment Revenue',
    'Corporate - WLS Equipment Revenue',
    'Consumer - Volume/Services',
    'Business - Volume/Services',
    'Fiber',
    'Mobility and Broadband Service Revenue',
    'Corporate - VZ WLN Less Fiber',
    'Consumer - VZ WLN Less Fiber',
    'Business - VZ WLN Less Fiber',
    'Consumer - FTR WLN Less Fiber',
    'Business - FTR WLN Less Fiber',
    'Corporate and Other',
    'Total Operating Revenues'
  ]) AS LineItem
)

SELECT c.LineItem, CAST(c.year AS STRING) AS year, CAST(c.month AS STRING) AS month, COALESCE(c.Amount, 0) AS Amount
FROM combined_3 AS c
JOIN output_items AS o
  ON c.LineItem = o.LineItem
ORDER BY c.LineItem, c.month_date;
